    assertEquals(c1.getNumberOfEntriesInBacklog(), 2);
    c1.rewind();
    assertEquals(c1.getNumberOfEntries(), 2);
    c1.markDelete(p4);
    assertEquals(c1.getNumberOfEntries(), 0);
    assertEquals(c1.getNumberOfEntriesInBacklog(), 0);
