    assertFalse(ensemble2.getZkClient().getState().isConnected());
    assertFalse(ensemble2.getBookies()[0].isRunning());
    // Finaly delete data directories
    FileUtils.deleteDirectory(zkDir);
    FileUtils.deleteDirectory(bkDir);
